"""Actual independent JS iterators and strict primitive element types."""
CORE=r'''
function executeCircular7(row){const [kind,raw,operations,operands,newValues]=row.arguments,initial=raw.slice(),saved=raw.slice(),n=raw.length;function check(ok,message){if(!ok)throw Error(message);}function project(value){check(kind==='number'?Number.isInteger(value)&&value>=-2147483648&&value<=2147483647:typeof value==='string','Preserve the selected generic element type');return value;}const actor=new CircularArray(initial);
function readIterator(iterator){const result=[];let done=false;for(let i=0;i<=n;++i){const step=iterator.next();if(step.done){done=true;break;}result.push(project(step.value));}check(done&&result.length===n,'Iterators yield exactly the fixed number of elements');check(Boolean(iterator.next().done),'Exhausted iterators remain exhausted');return result;}
function snapshot(){return readIterator(actor[Symbol.iterator]());}
function twice(){const first=actor[Symbol.iterator](),second=actor[Symbol.iterator](),left=[],right=[];for(let i=0;i<n;++i){for(const [iterator,result] of [[first,left],[second,right]]){const step=iterator.next();check(!step.done,'Independent iterators must not consume each other');result.push(project(step.value));}}check(Boolean(first.next().done)&&Boolean(second.next().done),'Each independent iterator finishes after the fixed length');return [left,right];}
function unchanged(){return initial.length===saved.length&&initial.every((v,i)=>v===saved[i]);}snapshot();check(unchanged(),'Copy caller sequence storage');const results=[null];for(let i=1;i<operations.length;++i){const operation=operations[i],operand=operands[i],invalid=(operation==='Get'||operation==='Set')&&(operand<0||operand>=n),before=invalid?snapshot():null;let result;try{if(operation==='Get')result=project(actor.Get(operand));else if(operation==='Set'){check(actor.Set(operand,newValues[i])===undefined,'Set returns undefined');result=null;}else if(operation==='Rotate'){check(actor.Rotate(operand)===undefined,'Rotate returns undefined');result=null;}else if(operation==='Iterate')result=snapshot();else if(operation==='IterateTwice')result=twice();else throw Error('Unknown operation');check(!invalid,'Invalid indexing must raise RangeError');}catch(error){if(!(error instanceof RangeError)||!invalid)throw error;check(JSON.stringify(snapshot())===JSON.stringify(before),'Invalid indexing preserves state');result={error:'index'};}check(unchanged(),'Preserve caller initial values during updates');results.push(result);}return {actual:{results,finalValues:snapshot()},mutationOk:true};}
'''
